#include <bits/stdc++.h>
using namespace std;
#define INF 1'000'000'001
#define f first
#define s second
#define pb push_back
#define MAXN 1123456
#define pii pair<int,int>
#define pdd pair<double,double>
#define one 1
#define int long long
#define mp make_pair
#define ld long double
#define double long double
#define MOD 1000000007

int p,k;

int times_cycle(int n){
	int num=1;
	for(int i=0;i<n;i++){
		num*=k;
		num%=p;
	}
	if(num==1)return p;
	return 1;
}

bool seen[MAXN];

int32_t main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.precision(2);
    cout.setf(ios::fixed);

    cin>>p>>k;

    if(k==0 || k==1){
    	int resp=1;
    	for(int i=0;i<p-1;i++){
    		resp*=p;
    		resp%=MOD;
    	}
    	cout<<(resp*(k==1?p:1))%MOD<<endl;
    	return 0;
    }
    int resp=1;
    for(int i=1;i<p;i++){
    	if(seen[i])continue;
    	int x=i;
    	int c=0;
    	while(!seen[x]){
    		seen[x]=1;
    		x=(k*x)%p;
    		c++;
    	}
    	resp*=times_cycle(c);
    	resp%=MOD;
    }

    cout<<resp<<endl;




    return 0;
} 
